<?php require_once 'includes/functions.php';require_login();$category=(int)($_GET['category']??0);$cats=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();
$sql="SELECT q.*,c.name category,(SELECT COUNT(*) FROM questions WHERE quiz_id=q.id) question_count FROM quizzes q JOIN categories c ON c.id=q.category_id WHERE q.is_published=1";$params=[];if($category){$sql.=' AND q.category_id=?';$params[]=$category;}$sql.=' ORDER BY q.created_at DESC';$s=db()->prepare($sql);$s->execute($params);$quizzes=$s->fetchAll();$pageTitle='Quiz Categories';require 'includes/header.php';?>
<h1>Quiz Categories</h1><div class="actions"><a class="button <?=!$category?'':'secondary'?>" href="categories.php">All</a><?php foreach($cats as $c):?><a class="button <?=$category==$c['id']?'':'secondary'?>" href="categories.php?category=<?=$c['id']?>"><?=e($c['name'])?></a><?php endforeach;?></div><div class="grid"><?php foreach($quizzes as $q):?><article class="card"><span class="badge"><?=e($q['category'])?></span><h3><?=e($q['title'])?></h3><p><?=e($q['description'])?></p><p><?=$q['question_count']?> questions · <?=$q['time_limit_minutes']?> minutes</p><a class="button" href="instructions.php?id=<?=$q['id']?>">Instructions</a></article><?php endforeach;?><?php if(!$quizzes):?><p>No quizzes found.</p><?php endif;?></div>
<?php require 'includes/footer.php';?>
